arduino.setup:
Serial.begin(9600);
pinMode(${DO}, INPUT);
Serial.println(F("LDR Sensor Ready - type /guide for help"));

arduino.loop:
while (Serial.available()) {
  char c = Serial.read();
  static String _cmd${COMP_SUFFIX} = "";
  if (c == '\n') {
    _cmd${COMP_SUFFIX}.trim();
    if (_cmd${COMP_SUFFIX} == "/guide") {
      Serial.println(F("=== LDR Guide ==="));
      Serial.println(F("AO->A0, DO->D3"));
      Serial.println(F("Potentiometer sets DO threshold only"));
      Serial.println(F("AO reads 0-1023 always"));
      Serial.println(F("================"));
    }
    _cmd${COMP_SUFFIX} = "";
  } else {
    _cmd${COMP_SUFFIX} += c;
  }
}
int analog_${COMP_SUFFIX} = analogRead(${AO});
int digital_${COMP_SUFFIX} = digitalRead(${DO});
Serial.print("LDR Value: ");
Serial.print(analog_${COMP_SUFFIX});
Serial.print(" | Lux~");
Serial.print(pow(10.0, (analog_${COMP_SUFFIX} / 1023.0) * 4.0 - 1.0), 1);
Serial.print(" | Dark: ");
Serial.println(digital_${COMP_SUFFIX} == HIGH ? F("YES") : F("no"));
delay(300);
